(()=>{if(location.pathname.startsWith('/cms')||window.__rentcamMemberInstalled)return;window.__rentcamMemberInstalled=true;
const fields=[['name','Nama Sesuai KTP','text'],['phone','No. HP','tel'],['nik','NIK Sesuai KTP','text'],['job','Pekerjaan','text'],['company','Nama Perusahaan / Kampus','text'],['address','Alamat Domisili','textarea'],['email','Email','email'],['social','Akun Media Sosial','text'],['emergencyName','Nama Kontak Darurat','text',true],['emergencyPhone','No. HP / WhatsApp Kontak Darurat','tel',true]],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let dialog,photos={selfie:[],ktp:[]},urls=[],text='';
const icons={name:'<circle cx="12" cy="8" r="4"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/>',phone:'<path d="M8 3H5a2 2 0 0 0-2 2c0 9 7 16 16 16a2 2 0 0 0 2-2v-3l-5-2-2 2a14 14 0 0 1-6-6l2-2Z"/>',nik:'<rect x="3" y="5" width="18" height="14" rx="3"/><circle cx="8" cy="11" r="2"/><path d="M5 16c1-3 5-3 6 0M14 10h4M14 14h4"/>',job:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V4h8v3M3 12c5 4 13 4 18 0M12 12v4"/>',company:'<path d="M4 21V5l8-2v18M12 8h8v13M8 7v1M8 12v1M8 17v1M16 12v1M16 17v1M2 21h20"/>',address:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',email:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m3 7 9 6 9-6"/>',social:'<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><path d="M17 7h.01"/>',emergencyName:'<path d="M12 21s-9-5-9-12a5 5 0 0 1 9-3 5 5 0 0 1 9 3c0 7-9 12-9 12Z"/><path d="M9 12h6M12 9v6"/>',emergencyPhone:'<path d="M8 3H5a2 2 0 0 0-2 2c0 9 7 16 16 16a2 2 0 0 0 2-2v-3l-5-2-2 2a14 14 0 0 1-6-6l2-2Z"/>',photo:'<path d="M3 8h4l2-3h6l2 3h4v13H3Z"/><circle cx="12" cy="14" r="4"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',send:'<path d="m22 2-7 20-4-9-9-4Z"/><path d="m11 13 11-11"/>'};
function icon(key){return '<svg viewBox="0 0 24 24" aria-hidden="true">'+(icons[key]||icons.name)+'</svg>'}
const placeholders={name:'Nama lengkap sesuai KTP',phone:'08xxxxxxxxxx',nik:'16 digit NIK',job:'Contoh: Filmmaker',company:'Nama perusahaan atau kampus',address:'Alamat lengkap tempat tinggal',email:'nama@email.com',social:'Contoh: @namaakun',emergencyName:'Nama orang yang dapat dihubungi',emergencyPhone:'08xxxxxxxxxx'};
function fieldMarkup([key,label,type,optional]){return `<label class="rc-member-field" for="rcMember-${key}"><span class="rc-member-label">${icon(key)}<span>${label}</span>${optional?'<small>Opsional</small>':''}</span>${type==='textarea'?`<textarea id="rcMember-${key}" name="${key}" required maxlength="1000" rows="3" placeholder="${placeholders[key]}"></textarea>`:`<input id="rcMember-${key}" name="${key}" type="${type}" ${optional?'':'required'} maxlength="${key==='nik'?16:200}" placeholder="${placeholders[key]}" ${key==='nik'?'inputmode="numeric" pattern="[0-9]{16}" minlength="16" title="NIK harus 16 angka"':type==='tel'?'inputmode="tel" pattern="[+0-9 ()-]{8,20}" title="Masukkan nomor HP atau WhatsApp yang valid"':key==='name'?'minlength="2"':''}>`}</label>`}
function section(title,subtitle,keys,key){return `<section class="rc-member-section"><div class="rc-member-section-title"><span>${icon(key)}</span><div><h3>${title}</h3><p>${subtitle}</p></div></div><div class="rc-member-fields">${fields.filter(f=>keys.includes(f[0])).map(fieldMarkup).join('')}</div></section>`}
const memberStyle=document.createElement('link');memberStyle.rel='stylesheet';memberStyle.href='/member-registration-20261002.css?v=1';document.head.append(memberStyle);
function install(){const bottom=document.querySelector('.rc-app-nav');if(bottom&&!bottom.querySelector('[data-register-member]')){const button=document.createElement('button');button.type='button';button.dataset.registerMember='';button.setAttribute('aria-label','Daftar Member Baru');button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="8" r="4"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M19 8v6M16 11h6"/></svg><span>Daftar</span>';bottom.insertBefore(button,bottom.querySelector('[data-menu]')||bottom.querySelector('[href="/cart"]'));}const nav=document.querySelector('#drawer .rc-drawer-nav')||document.querySelector('#drawer');if(nav&&!nav.querySelector('[data-register-member]'))nav.insertAdjacentHTML('beforeend','<button class="drawer-link" type="button" data-register-member><span class="drawer-link-icon"><svg viewBox="0 0 24 24"><circle cx="9" cy="8" r="4"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M19 8v6M16 11h6"/></svg></span><span><b>Daftar Member Baru</b><small>Registrasi langsung ke WhatsApp</small></span></button>')}
function target(){let n=String(window.RENTCAM_CMS_CONFIG?.general?.marketingWhatsapp||window.RENTCAM_CMS_CONFIG?.general?.whatsapp||'').replace(/\D/g,'');if(n.startsWith('0'))n='62'+n.slice(1);else if(n.startsWith('8'))n='62'+n;return n}
function message(f){return ['*FORM REGISTRASI MEMBER BARU*','',...fields.map(([key,label,,optional])=>label+': '+(f.elements[key].value.trim()||(optional?'Tidak diisi (opsional)':''))),'','*LAMPIRAN*','Foto selfie: '+photos.selfie.length+' foto','Foto KTP: '+photos.ktp.length+' foto','','Foto selfie dan KTP disertakan bersama registrasi ini.'].join('\n')}
function preview(){urls.forEach(URL.revokeObjectURL);urls=[];for(const kind of ['selfie','ktp']){const host=dialog.querySelector('[data-member-photos='+kind+']');host.innerHTML=photos[kind].map((file,i)=>{const u=URL.createObjectURL(file);urls.push(u);return `<div><img src="${u}" alt="${kind==='ktp'?'KTP':'Selfie'} ${i+1}"><span>${esc(file.name)}</span><button type="button" data-member-remove="${kind}" data-index="${i}">Hapus</button></div>`}).join('')}update()}
function update(){const f=dialog.querySelector('form');const host=dialog.querySelector('[data-member-summary]');host.innerHTML='<h3>Rincian registrasi</h3><dl>'+fields.map(([k,l,,optional])=>'<div><dt>'+l+'</dt><dd>'+esc(f.elements[k].value.trim()||(optional?'Tidak diisi (opsional)':'Belum diisi'))+'</dd></div>').join('')+'<div><dt>Foto selfie</dt><dd>'+photos.selfie.length+' foto</dd></div><div><dt>Foto KTP</dt><dd>'+photos.ktp.length+' foto</dd></div></dl>';text=message(f)}
function close(){urls.forEach(URL.revokeObjectURL);urls=[];photos={selfie:[],ktp:[]};text='';dialog?.remove();dialog=null}
function open(){if(dialog)return;document.getElementById('drawer')?.classList.remove('open');document.body.classList.remove('menu-open');dialog=document.createElement('dialog');dialog.id='rcMemberDialog';dialog.setAttribute('aria-labelledby','rcMemberTitle');dialog.innerHTML=`<div class="rc-member-header"><span class="rc-member-header-icon">${icon('name')}</span><div><h2 id="rcMemberTitle">Daftar Member</h2><p>Lengkapi data, lalu kirim ke marketing.</p></div><button type="button" data-member-close aria-label="Tutup form">×</button></div><form autocomplete="off"><div class="rc-member-scroll">${section('Identitas pribadi','Data sesuai identitas Anda.',['name','phone','nik','address'],'nik')}${section('Aktivitas & kontak','Informasi pekerjaan dan akun Anda.',['job','company','email','social'],'job')}${section('Kontak darurat','Opsional · Orang terdekat yang dapat dihubungi.',['emergencyName','emergencyPhone'],'emergencyName')}<section class="rc-member-section"><div class="rc-member-section-title"><span>${icon('photo')}</span><div><h3>Foto identitas</h3><p>Tambahkan foto selfie dan KTP yang jelas.</p></div></div><div class="rc-member-upload-grid">${['selfie','ktp'].map(kind=>`<section class="rc-member-upload"><div class="rc-member-upload-top">${icon(kind==='selfie'?'photo':'nik')}<h4>Foto ${kind==='selfie'?'selfie':'KTP'}</h4><span>Wajib</span></div><p>Maks. 10 foto, masing-masing 10 MB.</p><label class="rc-member-upload-button">${icon('photo')}<span>Tambah foto</span><input type="file" data-member-upload="${kind}" accept="image/*" multiple aria-label="Tambah foto ${kind}"></label><div class="rc-member-photos" data-member-photos="${kind}"></div></section>`).join('')}</div></section><details class="rc-member-summary"><summary>Periksa rincian registrasi <span aria-hidden="true">⌄</span></summary><section data-member-summary></section></details><p class="rc-member-note">${icon('shield')}<span>Data dan foto hanya digunakan untuk berbagi ke WhatsApp. Tidak disimpan ke database atau server, dan akan kosong saat form ditutup.</span></p></div><div class="rc-member-footer"><p role="status" data-member-status></p><button type="submit" class="btn">${icon('send')}<span>Kirim Registrasi</span></button><small>Pilih WhatsApp → pilih chat marketing → Kirim.</small></div></form>`;document.body.append(dialog);const openedDialog=dialog;dialog.addEventListener('close',()=>{if(dialog===openedDialog)close()});dialog.querySelector('[data-member-close]').onclick=()=>{dialog.close();close()};dialog.querySelector('form').addEventListener('input',update);dialog.addEventListener('change',e=>{const kind=e.target.dataset.memberUpload;if(!kind)return;const list=[...e.target.files],status=dialog.querySelector('[data-member-status]');if(list.some(f=>f.size>10*1024*1024||!f.type.startsWith('image/'))||photos[kind].length+list.length>10){status.textContent='Pilih maksimal 10 foto per bagian, masing-masing sampai 10 MB.';e.target.value='';return}photos[kind].push(...list);e.target.value='';status.textContent='';preview()});dialog.addEventListener('click',async e=>{const del=e.target.closest('[data-member-remove]');if(del){photos[del.dataset.memberRemove].splice(Number(del.dataset.index),1);preview()}});dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const status=dialog.querySelector('[data-member-status]');if(!photos.selfie.length||!photos.ktp.length){status.textContent='Tambahkan minimal satu foto selfie dan satu foto KTP.';return}text=message(f);const files=[...photos.selfie,...photos.ktp],button=f.querySelector('[type=submit]');if(!navigator.share||!navigator.canShare?.({files})){status.textContent='Browser ini belum mendukung berbagi foto. Buka form di Safari atau Chrome pada HP, lalu pilih WhatsApp saat mengirim.';return}button.disabled=true;status.textContent='Pilih WhatsApp lalu chat marketing '+(target()||'rental')+'. Teks dan seluruh foto dibagikan bersama.';try{await navigator.share({files,text,title:'Registrasi Member Rental'});if(dialog)status.textContent='Menu berbagi selesai. Periksa teks dan seluruh foto di chat WhatsApp sebelum menekan Kirim.'}catch(error){if(dialog)status.textContent=error.name==='AbortError'?'Pengiriman dibatalkan. Data dan foto masih tersedia; tekan tombol kirim untuk mencoba lagi.':'Foto dan teks belum dibagikan. Coba kembali melalui browser HP yang mendukung berbagi lampiran.'}finally{if(dialog)button.disabled=false}};update();dialog.showModal()}
document.addEventListener('click',e=>{if(e.target.closest('[data-register-member]')){e.preventDefault();open()}},true);const drawer=document.getElementById('drawer');if(drawer)new MutationObserver(install).observe(drawer,{childList:true,subtree:true});new MutationObserver(install).observe(document.body,{childList:true,subtree:true});install();
})();
